#include <linux/bpf.h>
#include <bpf/bpf_helpers.h>

SEC("xdp")
int xdp_drop_syn_flood(struct xdp_md *ctx) {
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    // Verify Ethernet & IP headers within packet bounds
    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end) return XDP_PASS;

    return XDP_DROP;
}
char _license[] SEC("license") = "GPL";

import Redlock from 'redlock';
import { redisCluster } from './redis';

const redlock = new Redlock(redisCluster, {
  driftFactor: 0.01,
  retryCount: 10,
  retryDelay: 200,
});

export async function processSeatReservation(seatId: string, userId: string) {
  // Acquire lock with 5000ms TTL
  const lock = await redlock.acquire([`locks:seat:${seatId}`], 5000);
  try {
    await db.booking.create({ data: { seatId, userId } });
  } finally {
    await lock.release();
  }
}
